def bucket_of(s):
    s_lower = s.lower()

    water_words = ["water", "wet", "wash"]
    slime_phrases = ["i don't know", "slime"]

    has_water = False
    has_slime = False

    for word in water_words:
        if word in s_lower:
            has_water = True
            break

    for phrase in slime_phrases:
        if phrase in s_lower:
            has_slime = True
            break

    if has_water and has_slime:
        return "sludge"
    elif has_water:
        return "water"
    elif has_slime:
        return "slime"
    else:
        return "air"
